problems.solution:
def column(M, j):
    """Column j of M (a list of rows)."""
    return [row[j] for row in M]


def matvec(M, v):
    n_rows, n_cols = len(M), len(M[0])
    if len(v) != n_cols:
        raise ValueError("vector length must equal the number of columns")
    result = [0] * n_rows
    for j in range(n_cols):
        col = column(M, j)
        for i in range(n_rows):
            result[i] += v[j] * col[i]
    return result

