problems.solution:
import numpy as np

def transform(M, pts):
    return M @ pts


def rotation(degrees):
    t = np.radians(degrees)
    return np.array([[np.cos(t), -np.sin(t)],
                     [np.sin(t),  np.cos(t)]])
